<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__).'/database/staging/academic-alignment/';$read=static fn($f)=>json_decode(file_get_contents($root.$f),true,512,JSON_THROW_ON_ERROR);$n=0;
function mapping_check(bool$ok,string$label):void{global$n;$n++;if(!$ok)throw new RuntimeException('FAIL: '.$label);}
$legacy=$read('legacy-academic-review-inputs.json');$review=$read('legacy-mapping-review.json');$rec=$read('mapping-review-receipt.json');$input=json_decode(file_get_contents($rec['privateDirectory'].'/student-inputs.json'),true,512,JSON_THROW_ON_ERROR);unset($input['history'],$input['enrollment']);
mapping_check(count($review['courses'])===240,'All 240 legacy courses reviewed');mapping_check(count(array_unique(array_column($review['courses'],'legacyCourseCode')))===240,'Course review unique');mapping_check(count($review['programs'])===24,'All legacy major/minor definitions reviewed');
$by=[];foreach($legacy['courses']as$c)$by[$c['course_ID']]=$c;
foreach($review['courses']as$c){mapping_check($c['equivalenceApproved']===false,'No title-similarity approval');mapping_check($c['legacyDescription']===$by[$c['legacyCourseCode']]['course_DSC'],'Original content retained');if($c['legacyAcademicLevel']==='Graduate')mapping_check($c['status']==='excluded-graduate-preserve'&&!$c['planningScenarioTarget'],'Graduate course excluded');foreach($c['candidates']as$x){mapping_check(!$x['approved'],'Candidate is not approval');mapping_check($x['catalogPrerequisiteRecord']!==null,'Target prerequisite evidence retained');if($c['planningScenarioTarget']===$x['courseVersionOrCode'])mapping_check($x['creditSnapshotFits'],'Projection cannot alter historical credit value');}}
$students=[];foreach($input['students']as$s)$students[$s['student_ID']]=$s;$seen=[];$ug=0;$grad=0;$audits=0;
$stream=fopen($rec['privateDirectory'].'/student-mapping-projections.json','r');fgets($stream);while(($line=fgets($stream))!==false){$line=trim($line);if(str_starts_with($line,']'))break;$s=json_decode(trim($line,','),true,512,JSON_THROW_ON_ERROR);mapping_check(isset($students[$s['studentId']])&&!isset($seen[$s['studentId']]),'Private report covers a unique existing student');$seen[$s['studentId']]=true;mapping_check($s['verifiedDegreeResult']===null&&$s['recordsChanged']===0,'No student verdict or mutation');if($s['level']==='Graduate'){$grad++;mapping_check($s['status']==='excluded-graduate-preserve'&&!isset($s['candidateAudits']),'Graduate not converted');continue;}$ug++;mapping_check($s['approvedProgramAssignment']===null&&$s['approvedEquivalencies']===[],'Undergraduate mappings remain unapproved');foreach($s['candidateAudits']as$a){$audits++;mapping_check($a['verifiedDegreeResult']===null&&!($a['engineResultUnderAssumptions']['graduationReady']??false),'Projection never becomes verified completion');}}
mapping_check(count($seen)===3338&&$ug===2200&&$grad===1138,'Full student and level coverage');mapping_check($audits===3852,'All candidate program/path diagnostics accounted for');
mapping_check((fileperms($rec['privateDirectory'])&0777)===0700,'Private directory protected');mapping_check((fileperms($rec['privateDirectory'].'/student-mapping-projections.json')&0777)===0600,'Private report protected');echo "PASS: $n course/program/student mapping review checks. No database/network access.\n";
